<?php require 'inc/bootstrap.php';require 'inc/ui.php';require 'inc/report.php';need_login();if(!is_owner())deny('Only the website owner can see the reports.');
$r=in_array($_GET['r']??'',['today','yesterday','7d'],true)?$_GET['r']:'24h';[$from,$to,$label]=rep_range($r);
if(isset($_GET['file'])){$f=basename((string)$_GET['file']);$path=__DIR__.'/data/reports/'.$f;if(preg_match('/^nova-report-[0-9_-]+\.pdf$/',$f)&&is_file($path)){while(ob_get_level())ob_end_clean();header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.$f.'"');readfile($path);exit;}http_response_code(404);exit('Not found');}
if(isset($_GET['pdf'])){$d=report_data($from,$to);[$path,$name]=report_save($d,$label);logit('report_download',$name);while(ob_get_level())ob_end_clean();header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.$name.'"');readfile($path);exit;}
if($_SERVER['REQUEST_METHOD']=='POST'){check_csrf();[$res,$name]=send_report($from,$to,$label);logit('report_sent',"$name (manual) → ".json_encode($res));$bad=array_filter($res,fn($x)=>$x!=='sent');
 if($bad)$_SESSION['flash']='The report was generated but could not be sent: '.json_encode($bad).' (the owner must allow DMs from server members).';else $_SESSION['ok']='✅ The report was sent to your Discord DM.';header('Location: /report.php?r='.$r);exit;}
$d=report_data($from,$to);$files=array_reverse(glob(__DIR__.'/data/reports/nova-report-*.pdf')?:[]);include 'inc/header.php';?>
<div class="sp"><div class="dl-head"><div><h2 class="title">WEBSITE REPORT</h2><p class="sub"><?=h($label)?>: <?=h(rep_loc($d['from'],'d/m/Y H:i'))?> → <?=h(rep_loc($d['to'],'d/m/Y H:i'))?> (<?=REP_TZ?>)</p></div>
<div><a class="btn" href="?pdf=1&r=<?=$r?>">DOWNLOAD PDF</a><form method="post" class="inl"><input type="hidden" name="csrf" value="<?=csrf()?>"><button class="btn ghost">SEND TO MY DM</button></form></div></div><?=flash_html()?>
<form method="get" class="sb"><?php foreach(['24h'=>'Last 24 hours','today'=>'Today','yesterday'=>'Yesterday','7d'=>'Last 7 days'] as $k=>$l):?><a class="btn sm <?=$k==$r?'':'ghost'?>" href="?r=<?=$k?>"><?=$l?></a><?php endforeach;?></form>
<p class="sub">A PDF report is sent automatically to the owner’s Discord DM every 24 hours (the bot must be online).</p>
<div class="stats-cards"><?php foreach([['Actions',$d['actions']],['Active members',$d['active']],['Logins',$d['logins']],['Shop orders',$d['orders']],['Revenue','$'.number_format($d['revenue'],2)],['Applications',$d['apps_new']],['Tickets opened',$d['t_open']],['New cheaters',$d['cheaters']],['Warns',$d['warns']],['Suggestions',$d['sug']],['Discord messages',number_format($d['msgs'])],['Voice hours',$d['voice']],['Joins',$d['joins']],['Leaves',$d['leaves']]] as $c):?><div><b><?=h($c[1])?></b><small><?=strtoupper(h($c[0]))?></small></div><?php endforeach;?></div>
<div class="card"><h3>Activity <?=$d['chart']['unit']==3600?'per hour':'per day'?></h3><?php $mx=max(1,max($d['chart']['values']));?><div class="bars" style="height:90px"><?php foreach($d['chart']['values'] as $i=>$v):?><i style="height:<?=$v?max(4,round($v/$mx*100)):0?>%" title="<?=h($d['chart']['labels'][$i])?>: <?=$v?> actions"></i><?php endforeach;?></div><small class="sub"><?=h($d['chart']['labels'][0])?> → <?=h(end($d['chart']['labels']))?></small></div>
<div class="card"><h3>Notes</h3><?php foreach($d['notes'] as $n):?><p class="note-l <?=$n[0]?>"><?=['ok'=>'✅','warn'=>'⚠️','info'=>'ℹ️'][$n[0]]?> <?=h($n[1])?></p><?php endforeach;?></div>
<div class="podium"><div class="card"><h4>WHAT HAPPENED</h4><ol><?php foreach($d['by_action'] as $a):?><li><span><?=h($a['action'])?></span><b><?=$a['c']?></b></li><?php endforeach;?><?php if(!$d['by_action']):?><li class="sub">Nothing yet</li><?php endif;?></ol></div>
<div class="card"><h4>MOST ACTIVE MEMBERS</h4><ol><?php foreach($d['by_user'] as $a):?><li><span><?=h($a['n'])?></span><b><?=$a['c']?></b></li><?php endforeach;?><?php if(!$d['by_user']):?><li class="sub">Nobody yet</li><?php endif;?></ol></div></div>
<div class="card"><h3>Activity log <small>(<?=count($d['logs'])?>)</small></h3><table><tr><th>Time</th><th>Member</th><th>Action</th><th>Details</th></tr><?php foreach(array_slice($d['logs'],0,150) as $l):?><tr><td><?=h(rep_loc($l['created_at']))?></td><td><?=h($l['actor_name'])?></td><td><b><?=h($l['action'])?></b></td><td><?=h($l['details'])?></td></tr><?php endforeach;?></table><p class="sub">The PDF contains up to 400 entries.</p></div>
<div class="card"><h3>Saved reports</h3><?php foreach(array_slice($files,0,30) as $f):$b=basename($f);?><div class="row" style="border-bottom:1px solid var(--b);padding:8px 0"><span><?=h($b)?></span><a class="btn sm" href="?file=<?=h(urlencode($b))?>">DOWNLOAD</a></div><?php endforeach;?><?php if(!$files):?><p class="sub">No saved report yet.</p><?php endif;?></div></div>
